<script setup lang="ts">
import { computed, ref } from 'vue';
import { ArrowRight, CircleHelp, Download, ExternalLink, Monitor, Search, Smartphone } from 'lucide-vue-next';
import clients from '../data/clients.json';
import { t } from '../i18n';
import PageHeading from '../components/PageHeading.vue';
import '../styles/member-ui.css';
const platforms=['Windows','macOS','Linux','Android','iOS / iPadOS'];
const platform=ref(''),search=ref('');
const visible=computed(()=>clients.filter(c=>(!platform.value||c.downloads.some(d=>d.platform===platform.value))&&(!search.value.trim()||[c.name,c.format,...c.protocols].some(v=>v.toLowerCase().includes(search.value.trim().toLowerCase())))));
const downloads=(client:typeof clients[number])=>client.downloads.filter(d=>!platform.value||d.platform===platform.value);
</script>
<template>
  <section class="member-page clients-page">
    <PageHeading :title="t('客户端中心')" :description="t('选择适合设备的客户端，下载后继续导入订阅。')" eyebrow="CLIENTS"><template #actions><RouterLink class="member-link" to="/subscription?connect=1">{{t('连接向导')}}<ArrowRight :size="16"/></RouterLink></template></PageHeading>
    <ol class="client-steps"><li><span>01</span><div><strong>{{t('选择你的设备')}}</strong><p>{{t('按操作系统下载对应安装包')}}</p></div></li><li><span>02</span><div><strong>{{t('导入订阅')}}</strong><p>{{t('在订阅页面复制地址或扫描二维码')}}</p></div></li><li><span>03</span><div><strong>{{t('开始连接')}}</strong><p>{{t('在客户端选择节点并开启连接')}}</p></div></li></ol>
    <div class="member-toolbar"><div class="member-tabs platforms" role="group" :aria-label="t('选择操作系统')"><button :aria-pressed="!platform" @click="platform=''">{{t('全部平台')}}</button><button v-for="p in platforms" :key="p" :aria-pressed="platform===p" @click="platform=p"><component :is="p==='Android'||p==='iOS / iPadOS'?Smartphone:Monitor" :size="15"/>{{p}}</button></div><label class="client-search"><Search :size="16"/><input v-model="search" type="search" :placeholder="t('搜索客户端')" :aria-label="t('搜索客户端')"/></label></div>
    <details class="client-help"><summary><CircleHelp :size="16"/>{{t('不确定选择哪个安装包？')}}</summary><p>{{t('Apple Silicon 选择 ARM64，Intel / AMD 电脑通常选择 x64；Android 请在设备信息中核对架构。直链为已核实版本，其他格式或新版请打开官方发布页。')}}</p></details>
    <div v-if="visible.length" class="client-grid">
      <article v-for="client in visible" :key="client.id" class="member-panel client-card">
        <header><div class="client-mark" aria-hidden="true">{{client.name.slice(0,2)}}</div><div><h2>{{client.name}}</h2><small>{{client.version?'v'+client.version:t('商店分发')}}</small></div><span :class="['member-status',client.paid?'':'active']">{{client.paid?t('付费'):t('免费')}}</span></header>
        <div class="client-tags"><span v-for="protocol in client.protocols" :key="protocol">{{protocol}}</span><span>{{client.format}}</span></div>
        <p class="client-note">{{t(client.note)}}</p>
        <div class="downloads"><a v-for="link in downloads(client)" :key="link.url" :href="link.url" target="_blank" rel="noopener noreferrer" :aria-label="client.name+' · '+link.platform+' · '+link.arch"><Download :size="16"/><span>{{link.platform}}<strong>{{link.arch}}</strong></span><ExternalLink :size="14"/></a></div>
        <RouterLink class="member-button client-setup" :to="{path:'/subscription',query:{connect:'1',client:client.id,...(platform?{platform}:{})}}">{{t('使用此客户端')}}<ArrowRight :size="16"/></RouterLink><footer><a :href="client.source" target="_blank" rel="noopener noreferrer">{{t('官方发布页')}}<ExternalLink :size="14"/></a><small>{{t('链接核实于')}} 2026-09-16</small></footer>
      </article>
    </div>
    <div v-else class="member-empty"><Search :size="30"/><h2>{{t('没有匹配的客户端')}}</h2><p>{{t('试试其他名称或切换操作系统。')}}</p><button @click="search='';platform=''">{{t('清除筛选')}}</button></div>
  </section>
</template>
